def is_undulating(n): 
    n = str(n)
    if len(n) <= 2:
        return False

    is_undulating = True
    for i in range(2, len(n)):
        if n[i] == n[i-1]:
            return False

        if i % 2 == 0:
            if n[i] != n[0]:
                is_undulating = False
                break
        else:
            if n[i] != n[1]:
                is_undulating = False
                break

    return is_undulating
```

