def is_undulating(n): 
	n = str(n)
	if len(n) <= 2: 
		return False

	# Check for repeating pattern of length 2 (e.g., 121212)
	is_repeating = True
	for i in range(2, len(n)): 
		if n[i] != n[i-2]: 
			is_repeating = False
			break

	if is_repeating:
		return False

	# Check for undulating pattern (e.g., 121, 12321)
	is_undulating = True
	for i in range(2, len(n)): 
		if n[i] != n[i-2]: 
			is_undulating = False
			break

	return is_undulating
```

