def search(arr):
    n = len(arr)
    if n == 0:
        return None
    left, right = 0, n - 1
    while left <= right:
        mid = (left + right) // 2
        # Check if mid is the first element of a pair
        if (mid == 0 or arr[mid] != arr[mid - 1]) and (mid == n - 1 or arr[mid] != arr[mid + 1]):
            return arr[mid]
        if arr[mid] == arr[mid + 1]:
            # Pair starts at mid or before, search left
            right = mid - 1
        else:
            # Pair starts after mid, search right
            left = mid + 1
    return arr[left] if left < n else None
```

