def search(arr):
    n = len(arr)
    if n == 0:
        return -1

    left, right = 0, n - 1

    while left < right:
        mid = (left + right) // 2

        # Check if mid is even or odd
        if mid % 2 == 1:
            # If mid is odd, compare arr[mid] with arr[mid-1]
            if arr[mid] == arr[mid-1]:
                left = mid + 1
            else:
                right = mid
        else:
            # If mid is even, compare arr[mid] with arr[mid+1]
            if arr[mid] == arr[mid+1]:
                left = mid + 1
            else:
                right = mid

    return arr[left]
```

