def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        return None if n % b != 0 else (0, n // b)
    if b == 0:
        return None if n % a != 0 else (n // a, 0)

    g = 1
    x1, y1 = 0, 1
    b1, a1 = b, a
    while a1 != 0:
        q = b1 // a1
        b1, a1 = a1, b1 % a1
        x1, y1 = y1 - q * x1, x1

    if n % g != 0:
        return None

    x = x1 * (n // g)
    y = y1 * (n // g)

    while y < 0:
        y += a // g
        x -= b // g

    return (x, y)
```

