import math

def div_sum(n):
    if n <= 1:
        return 0
    total = 1  # Start with 1 since 1 is a divisor for all n > 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            total += i
            if i != n // i:  # Add the pair divisor if it's different
                total += n // i
        i += 1
    return total

def are_equivalent(num1, num2):
    return div_sum(num1) == div_sum(num2)
```

