        elif arr[mid] > x:
            return binary_search_first(arr, low, mid - 1, x)
        else:
            return binary_search_first(arr, mid + 1, high, x)

    def binary_search_last(arr, low, high, x):
        if high < low:
            return -1
        mid = (low + high) // 2
        if arr[mid] == x:
            if mid == n - 1 or arr[mid + 1] != x:
                return mid
            else:
                return binary_search_last(arr, mid + 1, high, x)
        elif arr[mid] < x:
            return binary_search_last(arr, mid + 1, high, x)
        else:
            return binary_search_last(arr, low, mid - 1, x)

    first_occurrence = binary_search_first(arr, 0, n - 1, x)
    if first_occurrence == -1:
        return False

    last_occurrence = binary_search_last(arr, first_occurrence, n - 1, x)

    count = last_occurrence - first_occurrence + 1
    return count > n // 2
