def get_max_sum(n):
    if n == 0:
        return 0
    if n == 1:
        return 1

    # Cache to store results of subproblems
    memo = {0: 0, 1: 1}

    def solve(k):
        if k in memo:
            return memo[k]

        # Calculate the sum of recursive calls
        # Note: k//2, k//3, etc. are integer divisions
        recursive_sum = solve(k // 2) + solve(k // 3) + solve(k // 4) + solve(k // 5)

        # The result for k is the maximum of k itself and the recursive sum
        result = max(k, recursive_sum)
        memo[k] = result
        return result

    return solve(n)
```

