def cal_sum(n): 
    if n == 0:
        return 0
    elif n == 1:
        return 1
    elif n == 2:
        return 2

    p0, p1, p2 = 0, 1, 2
    total = p0 + p1 + p2  # Sum for n=2 is 3 (0+1+2)

    for i in range(3, n + 1):
        p_next = p0 + p1 + p2
        p0, p1, p2 = p1, p2, p_next
        total += p_next

    return total
```

