import math

def sumofFactors(n):
    # If n is odd, it has no even factors (except 0 which isn't a factor)
    if n % 2 != 0:
        return 0

    total_sum = 0
    # Iterate through all numbers up to n to find factors
    for i in range(2, n + 1):
        if n % i == 0:
            # Check if the factor is even
            if i % 2 == 0:
                total_sum += i

    return total_sum
```

