def max_product(arr):
    if not arr:
        return 0

    n = len(arr)
    # dp[i] will store the maximum product of an increasing subsequence ending at index i
    dp = [x for x in arr]

    for i in range(n):
        current_max = arr[i]
        # Look backwards to find an increasing subsequence
        for j in range(i):
            if arr[j] < arr[i]:
                # If extending the subsequence ending at j gives a larger product
                if dp[j] * arr[i] > current_max:
                    current_max = dp[j] * arr[i]
        dp[i] = current_max

    return max(dp)
```

